  `ethnicity` varchar(100) DEFAULT NULL,
  `religion` varchar(100) DEFAULT NULL,
  `birth_place_original` varchar(500) DEFAULT NULL,
  `birth_place_current` varchar(500) DEFAULT NULL,
  `education_level` varchar(255) DEFAULT NULL,
  `major` varchar(255) DEFAULT NULL,
  `employment_status` varchar(16) NOT NULL DEFAULT 'DRAFT',
  `status_effective_date` date DEFAULT NULL,
  `source_import_batch_id` varchar(36) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_by_actor` varchar(320) NOT NULL,
  `updated_by_actor` varchar(320) NOT NULL,
  `row_version` bigint NOT NULL DEFAULT '0',
  `workforce_group` varchar(32) NOT NULL DEFAULT 'LEGACY_UNKNOWN',
  `onboarding_source` varchar(32) NOT NULL DEFAULT 'LEGACY',
  `onboarding_policy_version` smallint NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hr_employee_code` (`employee_code`),
  KEY `idx_hr_employees_status_code` (`employment_status`,`employee_code`),
  KEY `idx_hr_employees_full_name` (`full_name`),
  KEY `idx_hr_employees_source_batch` (`source_import_batch_id`),
  KEY `idx_hr_employees_workforce_status` (`workforce_group`,`employment_status`,`employee_code`),
  CONSTRAINT `fk_hr_employee_source_batch` FOREIGN KEY (`source_import_batch_id`) REFERENCES `hr_excel_import_batches` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_hr_employee_gender` CHECK ((`gender` in (_utf8mb4'MALE',_utf8mb4'FEMALE',_utf8mb4'OTHER',_utf8mb4'UNKNOWN'))),
  CONSTRAINT `ck_hr_employee_onboarding_policy` CHECK ((`onboarding_policy_version` >= 1)),
  CONSTRAINT `ck_hr_employee_onboarding_source` CHECK ((`onboarding_source` in (_utf8mb4'PROBATION',_utf8mb4'DIRECT_GENERAL_LABOR',_utf8mb4'MANUAL',_utf8mb4'IMPORT',_utf8mb4'LEGACY'))),
  CONSTRAINT `ck_hr_employee_row_version` CHECK ((`row_version` >= 0)),
  CONSTRAINT `ck_hr_employee_status` CHECK ((`employment_status` in (_utf8mb4'DRAFT',_utf8mb4'ACTIVE',_utf8mb4'INACTIVE'))),
  CONSTRAINT `ck_hr_employee_workforce_group` CHECK ((`workforce_group` in (_utf8mb4'OFFICE',_utf8mb4'GENERAL_LABOR',_utf8mb4'LEGACY_UNKNOWN')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;




DROP TABLE IF EXISTS `hr_employment_contract_documents`;
CREATE TABLE `hr_employment_contract_documents` (
  `id` varchar(36) NOT NULL,
  `employment_contract_id` varchar(36) NOT NULL,
  `workforce_group` varchar(32) NOT NULL,
  `template_file_name` varchar(255) NOT NULL,
  `template_sha256` char(64) NOT NULL,
  `generated_file_name` varchar(255) NOT NULL,
  `generated_file_sha256` char(64) NOT NULL,
  `generated_docx` mediumblob NOT NULL,
  `snapshot_payload` json NOT NULL,
  `generated_at` datetime(6) NOT NULL,
  `generated_by_actor` varchar(320) NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_by_actor` varchar(320) NOT NULL,
  `updated_by_actor` varchar(320) NOT NULL,
  `row_version` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_hr_employment_contract_document_contract` (`employment_contract_id`,`generated_at`),
  CONSTRAINT `fk_hr_employment_contract_document_contract` FOREIGN KEY (`employment_contract_id`) REFERENCES `hr_employment_contracts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_hr_employment_contract_document_group` CHECK ((`workforce_group` in (_utf8mb4'OFFICE',_utf8mb4'GENERAL_LABOR'))),
  CONSTRAINT `ck_hr_employment_contract_document_row_version` CHECK ((`row_version` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `hr_employment_contracts`;
CREATE TABLE `hr_employment_contracts` (
  `id` varchar(36) NOT NULL,
  `employee_id` varchar(36) NOT NULL,
  `source_probation_candidate_id` varchar(36) DEFAULT NULL,
  `contract_type` varchar(32) NOT NULL,
  `contract_number` varchar(100) NOT NULL,
  `sign_date` date NOT NULL,
  `effective_from` date NOT NULL,
  `effective_until` date DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'READY',
  `idempotency_key` varchar(100) NOT NULL,
  `activated_at` datetime(6) DEFAULT NULL,
  `activated_by_actor` varchar(320) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_by_actor` varchar(320) NOT NULL,
  `updated_by_actor` varchar(320) NOT NULL,
  `row_version` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hr_employment_contract_number` (`contract_number`),
  UNIQUE KEY `uk_hr_employment_contract_idempotency` (`idempotency_key`),
  KEY `idx_hr_employment_contract_employee_status` (`employee_id`,`status`,`effective_from`),
  KEY `idx_hr_employment_contract_probation` (`source_probation_candidate_id`),
  CONSTRAINT `fk_hr_employment_contract_employee` FOREIGN KEY (`employee_id`) REFERENCES `hr_employees` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_hr_employment_contract_probation` FOREIGN KEY (`source_probation_candidate_id`) REFERENCES `hr_probation_candidates` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_hr_employment_contract_activation` CHECK ((((`status` = _utf8mb4'EFFECTIVE') and (`activated_at` is not null) and (`activated_by_actor` is not null)) or (`status` <> _utf8mb4'EFFECTIVE'))),
  CONSTRAINT `ck_hr_employment_contract_dates` CHECK ((((`contract_type` = _utf8mb4'FIXED_TERM_12_MONTHS') and (`effective_until` is not null) and (`effective_until` > `effective_from`)) or ((`contract_type` = _utf8mb4'INDEFINITE') and (`effective_until` is null)))),
  CONSTRAINT `ck_hr_employment_contract_row_version` CHECK ((`row_version` >= 0)),
  CONSTRAINT `ck_hr_employment_contract_status` CHECK ((`status` in (_utf8mb4'READY',_utf8mb4'EFFECTIVE',_utf8mb4'VOIDED'))),
  CONSTRAINT `ck_hr_employment_contract_type` CHECK ((`contract_type` in (_utf8mb4'FIXED_TERM_12_MONTHS',_utf8mb4'INDEFINITE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `hr_excel_import_batches`;
CREATE TABLE `hr_excel_import_batches` (
  `id` varchar(36) NOT NULL,
  `template_version_id` varchar(36) DEFAULT NULL,
  `import_type` varchar(16) NOT NULL,
  `source_file_name` varchar(255) NOT NULL,
  `file_sha256` char(64) NOT NULL,
  `file_size` bigint NOT NULL,
  `storage_key` varchar(500) DEFAULT NULL,
  `source_sheet_name` varchar(100) NOT NULL,
  `attempt_number` int NOT NULL DEFAULT '1',
  `source_period_year` smallint DEFAULT NULL,
  `source_period_month` tinyint DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'UPLOADED',
  `total_rows` int NOT NULL DEFAULT '0',
  `valid_rows` int NOT NULL DEFAULT '0',
  `warning_rows` int NOT NULL DEFAULT '0',
  `invalid_rows` int NOT NULL DEFAULT '0',
  `imported_rows` int NOT NULL DEFAULT '0',
  `issue_summary` json DEFAULT NULL,
  `confirmation_key` varchar(100) DEFAULT NULL,
  `parsed_at` datetime(6) DEFAULT NULL,
  `validated_at` datetime(6) DEFAULT NULL,
  `confirmed_at` datetime(6) DEFAULT NULL,
  `confirmed_by_actor` varchar(320) DEFAULT NULL,
  `rolled_back_at` datetime(6) DEFAULT NULL,
  `rolled_back_by_actor` varchar(320) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_by_actor` varchar(320) NOT NULL,
  `updated_by_actor` varchar(320) NOT NULL,
  `row_version` bigint NOT NULL DEFAULT '0',
  `payload_retention_until` datetime(6) DEFAULT NULL,
  `payload_purged_at` datetime(6) DEFAULT NULL,
  `payload_purged_by_actor` varchar(320) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hr_import_file_attempt` (`file_sha256`,`source_sheet_name`,`import_type`,`attempt_number`),
  UNIQUE KEY `uk_hr_import_confirmation_key` (`confirmation_key`),
  KEY `fk_hr_import_template` (`template_version_id`),
  KEY `idx_hr_import_status_created` (`status`,`created_at`),
  KEY `idx_hr_import_file_sha` (`file_sha256`),
  KEY `idx_hr_import_payload_retention` (`payload_purged_at`,`payload_retention_until`,`status`),
  CONSTRAINT `fk_hr_import_template` FOREIGN KEY (`template_version_id`) REFERENCES `hr_excel_template_versions` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_hr_import_attempt` CHECK ((`attempt_number` > 0)),
  CONSTRAINT `ck_hr_import_count_totals` CHECK (((((`valid_rows` + `warning_rows`) + `invalid_rows`) <= `total_rows`) and (`imported_rows` <= (`valid_rows` + `warning_rows`)))),
  CONSTRAINT `ck_hr_import_counts` CHECK (((`total_rows` >= 0) and (`valid_rows` >= 0) and (`warning_rows` >= 0) and (`invalid_rows` >= 0) and (`imported_rows` >= 0))),
  CONSTRAINT `ck_hr_import_file_size` CHECK ((`file_size` > 0)),
  CONSTRAINT `ck_hr_import_lifecycle` CHECK (((`status` = _utf8mb4'FAILED') or ((`status` = _utf8mb4'UPLOADED') and (`parsed_at` is null) and (`validated_at` is null) and (`confirmed_at` is null) and (`rolled_back_at` is null)) or ((`status` = _utf8mb4'PARSED') and (`parsed_at` is not null) and (`validated_at` is null) and (`confirmed_at` is null) and (`rolled_back_at` is null)) or ((`status` = _utf8mb4'VALIDATED') and (`parsed_at` is not null) and (`validated_at` is not null) and (`confirmed_at` is null) and (`rolled_back_at` is null)) or ((`status` = _utf8mb4'CONFIRMED') and (`parsed_at` is not null) and (`validated_at` is not null) and (`confirmed_at` is not null) and (`confirmed_by_actor` is not null) and (`rolled_back_at` is null)) or ((`status` = _utf8mb4'ROLLED_BACK') and (`confirmed_at` is not null) and (`confirmed_by_actor` is not null) and (`rolled_back_at` is not null) and (`rolled_back_by_actor` is not null)))),
  CONSTRAINT `ck_hr_import_payload_purge_audit` CHECK ((((`payload_purged_at` is null) and (`payload_purged_by_actor` is null)) or ((`payload_purged_at` is not null) and (`payload_purged_by_actor` is not null)))),
  CONSTRAINT `ck_hr_import_period_month` CHECK (((`source_period_month` is null) or (`source_period_month` between 1 and 12))),
  CONSTRAINT `ck_hr_import_period_year` CHECK (((`source_period_year` is null) or (`source_period_year` between 1900 and 2200))),
  CONSTRAINT `ck_hr_import_row_version` CHECK ((`row_version` >= 0)),
  CONSTRAINT `ck_hr_import_status` CHECK ((`status` in (_utf8mb4'UPLOADED',_utf8mb4'PARSED',_utf8mb4'VALIDATED',_utf8mb4'CONFIRMED',_utf8mb4'FAILED',_utf8mb4'ROLLED_BACK'))),
  CONSTRAINT `ck_hr_import_type` CHECK ((`import_type` in (_utf8mb4'BASELINE',_utf8mb4'INCREASE',_utf8mb4'DECREASE',_utf8mb4'ROSTER')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `hr_excel_import_rows`;
CREATE TABLE `hr_excel_import_rows` (
  `id` varchar(36) NOT NULL,
  `batch_id` varchar(36) NOT NULL,
  `sheet_name` varchar(100) NOT NULL,
  `source_row_number` int NOT NULL,
  `employee_code_hint` varchar(32) DEFAULT NULL,
  `row_status` varchar(20) NOT NULL DEFAULT 'PENDING',
  `raw_payload` json DEFAULT NULL,
  `normalized_payload` json DEFAULT NULL,
  `payload_sha256` char(64) NOT NULL,
  `issue_codes` json DEFAULT NULL,
  `employee_id` varchar(36) DEFAULT NULL,
  `movement_id` varchar(36) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hr_import_row` (`batch_id`,`sheet_name`,`source_row_number`),
  KEY `fk_hr_import_row_movement` (`movement_id`),
  KEY `idx_hr_import_row_status` (`batch_id`,`row_status`,`source_row_number`),
  KEY `idx_hr_import_row_employee` (`employee_id`),
  CONSTRAINT `fk_hr_import_row_batch` FOREIGN KEY (`batch_id`) REFERENCES `hr_excel_import_batches` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_hr_import_row_employee` FOREIGN KEY (`employee_id`) REFERENCES `hr_employees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_hr_import_row_movement` FOREIGN KEY (`movement_id`) REFERENCES `hr_employee_movements` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ck_hr_import_row_number` CHECK ((`source_row_number` > 0)),
  CONSTRAINT `ck_hr_import_row_status` CHECK ((`row_status` in (_utf8mb4'PENDING',_utf8mb4'VALID',_utf8mb4'WARNING',_utf8mb4'INVALID',_utf8mb4'IMPORTED',_utf8mb4'SKIPPED',_utf8mb4'ROLLED_BACK')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `hr_excel_template_versions`;
CREATE TABLE `hr_excel_template_versions` (
  `id` varchar(36) NOT NULL,
  `template_key` varchar(64) NOT NULL,
  `version_code` varchar(32) NOT NULL,
  `schema_version` smallint NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `file_sha256` char(64) NOT NULL,
  `sheet_contract` json NOT NULL,
  `contains_pii` tinyint(1) NOT NULL DEFAULT '0',
  `status` varchar(16) NOT NULL DEFAULT 'DRAFT',
  `effective_from` date DEFAULT NULL,
  `effective_until` date DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_by_actor` varchar(320) NOT NULL,
  `updated_by_actor` varchar(320) NOT NULL,
  `row_version` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hr_template_key_version` (`template_key`,`version_code`),
  UNIQUE KEY `uk_hr_template_file_sha` (`file_sha256`),
  CONSTRAINT `ck_hr_template_dates` CHECK (((`effective_until` is null) or (`effective_from` is null) or (`effective_until` >= `effective_from`))),
  CONSTRAINT `ck_hr_template_row_version` CHECK ((`row_version` >= 0)),
  CONSTRAINT `ck_hr_template_schema_version` CHECK ((`schema_version` > 0)),
  CONSTRAINT `ck_hr_template_status` CHECK ((`status` in (_utf8mb4'DRAFT',_utf8mb4'ACTIVE',_utf8mb4'RETIRED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `hr_monthly_roster_items`;
CREATE TABLE `hr_monthly_roster_items` (
  `id` varchar(36) NOT NULL,
  `roster_id` varchar(36) NOT NULL,
  `employee_id` varchar(36) NOT NULL,
  `display_order` int NOT NULL,
  `department_display_order` int DEFAULT NULL,
  `employee_code` varchar(32) NOT NULL,
  `full_name` varchar(255) NOT NULL,
  `department_code` varchar(32) DEFAULT NULL,
  `department_name` varchar(255) DEFAULT NULL,
  `position_code` varchar(32) DEFAULT NULL,
  `position_name` varchar(255) DEFAULT NULL,
  `working_condition_code` varchar(32) DEFAULT NULL,
  `working_condition_name` varchar(255) DEFAULT NULL,
  `employment_status` varchar(16) NOT NULL,
  `hire_date` date DEFAULT NULL,
  `termination_date` date DEFAULT NULL,
  `leave_days` decimal(6,2) DEFAULT NULL,
  `inclusion_reason` varchar(20) NOT NULL,
  `source_movement_id` varchar(36) DEFAULT NULL,
  `snapshot_schema_version` smallint NOT NULL DEFAULT '1',
  `snapshot_payload` json NOT NULL,
  `payload_sha256` char(64) NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_by_actor` varchar(320) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hr_roster_item_employee` (`roster_id`,`employee_id`),
  UNIQUE KEY `uk_hr_roster_item_code` (`roster_id`,`employee_code`),
  UNIQUE KEY `uk_hr_roster_item_order` (`roster_id`,`display_order`),
  KEY `idx_hr_roster_item_employee` (`employee_id`,`roster_id`),
  KEY `idx_hr_roster_item_movement` (`source_movement_id`),
  CONSTRAINT `fk_hr_roster_item_employee` FOREIGN KEY (`employee_id`) REFERENCES `hr_employees` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_hr_roster_item_movement` FOREIGN KEY (`source_movement_id`) REFERENCES `hr_employee_movements` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_hr_roster_item_roster` FOREIGN KEY (`roster_id`) REFERENCES `hr_monthly_rosters` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_hr_roster_item_department_order` CHECK (((`department_display_order` is null) or (`department_display_order` > 0))),
  CONSTRAINT `ck_hr_roster_item_display_order` CHECK ((`display_order` > 0)),
  CONSTRAINT `ck_hr_roster_item_leave` CHECK (((`leave_days` is null) or (`leave_days` >= 0))),
  CONSTRAINT `ck_hr_roster_item_reason` CHECK ((`inclusion_reason` in (_utf8mb4'BASELINE',_utf8mb4'CARRIED_FORWARD',_utf8mb4'INCREASE',_utf8mb4'REHIRE',_utf8mb4'ADJUSTMENT'))),
  CONSTRAINT `ck_hr_roster_item_schema_version` CHECK ((`snapshot_schema_version` > 0)),
  CONSTRAINT `ck_hr_roster_item_status` CHECK ((`employment_status` in (_utf8mb4'DRAFT',_utf8mb4'ACTIVE',_utf8mb4'INACTIVE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;




DROP TABLE IF EXISTS `hr_monthly_rosters`;
CREATE TABLE `hr_monthly_rosters` (
  `id` varchar(36) NOT NULL,
  `period_start` date NOT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'DRAFT',
  `source_roster_id` varchar(36) DEFAULT NULL,
  `source_import_batch_id` varchar(36) DEFAULT NULL,
  `snapshot_schema_version` smallint NOT NULL DEFAULT '1',
  `item_count` int NOT NULL DEFAULT '0',
  `roster_checksum` char(64) DEFAULT NULL,
  `opened_at` datetime(6) DEFAULT NULL,
  `opened_by_actor` varchar(320) DEFAULT NULL,
  `closed_at` datetime(6) DEFAULT NULL,
  `closed_by_actor` varchar(320) DEFAULT NULL,
  `exported_at` datetime(6) DEFAULT NULL,
  `exported_by_actor` varchar(320) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_by_actor` varchar(320) NOT NULL,
  `updated_by_actor` varchar(320) NOT NULL,
  `row_version` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hr_roster_period` (`period_start`),
  KEY `idx_hr_roster_source` (`source_roster_id`),
  KEY `idx_hr_roster_import_batch` (`source_import_batch_id`),
  CONSTRAINT `fk_hr_roster_import_batch` FOREIGN KEY (`source_import_batch_id`) REFERENCES `hr_excel_import_batches` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_hr_roster_source` FOREIGN KEY (`source_roster_id`) REFERENCES `hr_monthly_rosters` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_hr_roster_item_count` CHECK ((`item_count` >= 0)),
  CONSTRAINT `ck_hr_roster_lifecycle` CHECK ((((`status` = _utf8mb4'DRAFT') and (`opened_at` is null) and (`closed_at` is null) and (`exported_at` is null)) or ((`status` = _utf8mb4'OPEN') and (`opened_at` is not null) and (`opened_by_actor` is not null) and (`closed_at` is null) and (`exported_at` is null)) or ((`status` = _utf8mb4'CLOSED') and (`opened_at` is not null) and (`opened_by_actor` is not null) and (`closed_at` is not null) and (`closed_by_actor` is not null) and (`exported_at` is null)) or ((`status` = _utf8mb4'EXPORTED') and (`closed_at` is not null) and (`closed_by_actor` is not null) and (`exported_at` is not null) and (`exported_by_actor` is not null)))),
  CONSTRAINT `ck_hr_roster_not_own_source` CHECK (((`source_roster_id` is null) or (`source_roster_id` <> `id`))),
  CONSTRAINT `ck_hr_roster_period_start` CHECK ((extract(day from `period_start`) = 1)),
  CONSTRAINT `ck_hr_roster_row_version` CHECK ((`row_version` >= 0)),
  CONSTRAINT `ck_hr_roster_schema_version` CHECK ((`snapshot_schema_version` > 0)),
  CONSTRAINT `ck_hr_roster_status` CHECK ((`status` in (_utf8mb4'DRAFT',_utf8mb4'OPEN',_utf8mb4'CLOSED',_utf8mb4'EXPORTED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `hr_positions`;
CREATE TABLE `hr_positions` (
  `id` varchar(36) NOT NULL,
  `code` varchar(32) NOT NULL,
  `name` varchar(255) NOT NULL,
  `description` varchar(1000) DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'ACTIVE',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_by_actor` varchar(320) NOT NULL,
  `updated_by_actor` varchar(320) NOT NULL,
  `row_version` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hr_position_code` (`code`),
  UNIQUE KEY `uk_hr_position_name` (`name`),
  CONSTRAINT `ck_hr_position_row_version` CHECK ((`row_version` >= 0)),
  CONSTRAINT `ck_hr_position_sort_order` CHECK ((`sort_order` >= 0)),
  CONSTRAINT `ck_hr_position_status` CHECK ((`status` in (_utf8mb4'ACTIVE',_utf8mb4'INACTIVE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `hr_probation_candidates`;
CREATE TABLE `hr_probation_candidates` (
  `id` varchar(36) NOT NULL,
  `candidate_code` varchar(32) NOT NULL,
  `full_name` varchar(255) NOT NULL,
  `candidate_title` varchar(16) DEFAULT NULL,
  `gender` varchar(16) NOT NULL DEFAULT 'UNKNOWN',
  `date_of_birth` date DEFAULT NULL,
  `birth_place` varchar(500) DEFAULT NULL,
  `nationality` varchar(100) NOT NULL DEFAULT 'Việt Nam',
  `citizen_id` varchar(32) DEFAULT NULL,
  `citizen_id_issued_date` date DEFAULT NULL,
  `citizen_id_issued_place` varchar(255) DEFAULT NULL,
  `permanent_address` varchar(1000) DEFAULT NULL,
  `phone` varchar(32) DEFAULT NULL,
  `email` varchar(320) DEFAULT NULL,
  `department_id` varchar(36) DEFAULT NULL,
  `position_id` varchar(36) DEFAULT NULL,
  `working_condition_id` varchar(36) DEFAULT NULL,
  `job_template_id` varchar(36) DEFAULT NULL,
  `probation_contract_type` varchar(100) DEFAULT NULL,
  `probation_start_date` date DEFAULT NULL,
  `probation_end_date` date DEFAULT NULL,
  `base_salary` decimal(15,2) DEFAULT NULL,
  `salary_note` varchar(255) DEFAULT NULL,
  `job_description` varchar(2000) DEFAULT NULL,
  `department_rule_note` varchar(500) DEFAULT NULL,
  `status` varchar(24) NOT NULL DEFAULT 'DRAFT',
  `status_reason` varchar(1000) DEFAULT NULL,
  `converted_employee_id` varchar(36) DEFAULT NULL,
  `converted_at` datetime(6) DEFAULT NULL,
  `converted_by_actor` varchar(320) DEFAULT NULL,
