  CONSTRAINT `ck_hr_probation_candidate_converted` CHECK ((((`status` = _utf8mb4'CONVERTED') and (`converted_employee_id` is not null) and (`converted_at` is not null) and (`converted_by_actor` is not null)) or ((`status` <> _utf8mb4'CONVERTED') and (`converted_employee_id` is null) and (`converted_at` is null) and (`converted_by_actor` is null)))),
